from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    results = []

    def add_if_valid(candidate):
        if candidate >= start_date:
            results.append(candidate.isoformat())
            return len(results) == count
        return False

    if kind == "DAILY":
        current = start_date
        step = timedelta(days=interval)
        while len(results) < count:
            results.append(current.isoformat())
            current += step
        return results

    if kind == "WEEKLY":
        weekday_codes = ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
        weekdays = {weekday_codes.index(code) for code in parts[2].split(",")}
        start_week = start_date - timedelta(days=start_date.weekday())
        week_index = 0

        while len(results) < count:
            week_start = start_week + timedelta(weeks=week_index)
            for weekday in sorted(weekdays):
                candidate = week_start + timedelta(days=weekday)
                if add_if_valid(candidate):
                    return results
            week_index += interval
        return results

    def month_date(year, month, day_rule, weekday=None):
        days_in_month = calendar.monthrange(year, month)[1]

        if weekday is None:
            day = days_in_month if day_rule == -1 else day_rule
            if day > days_in_month:
                return None
            return date(year, month, day)

        if day_rule == -1:
            last_day = date(year, month, days_in_month)
            return last_day - timedelta(days=(last_day.weekday() - weekday) % 7)

        first_weekday = date(year, month, 1).weekday()
        day = 1 + (weekday - first_weekday) % 7 + (day_rule - 1) * 7
        if day > days_in_month:
            return None
        return date(year, month, day)

    if kind == "MONTHLY":
        if len(parts) == 3:
            day_rule = int(parts[2])
            weekday = None
        else:
            day_rule = int(parts[2])
            weekday = ("MO", "TU", "WE", "TH", "FR", "SA", "SU").index(parts[3])

        start_month_index = start_date.year * 12 + start_date.month - 1
        month_index = start_month_index
        while len(results) < count:
            year, month0 = divmod(month_index, 12)
            candidate = month_date(year, month0 + 1, day_rule, weekday)
            if candidate is not None and add_if_valid(candidate):
                return results
            month_index += interval
        return results

    month, day = map(int, parts[2].split("-"))
    year = start_date.year
    while len(results) < count:
        candidate = None
        try:
            candidate = date(year, month, day)
        except ValueError:
            pass
        if candidate is not None and add_if_valid(candidate):
            return results
        year += interval
    return results
